def frequentest(xs):
    """Most frequent value in xs; ties broken by the smaller value."""
    counts = {}
    for x in xs:
        counts[x] = counts.get(x, 0) + 1
    best = None
    best_n = 0
    for x in sorted(counts):
        if counts[x] > best_n:
            best = x
            best_n = counts[x]
    return best

