def run_length_encode(s):
    """Run-length encode a string: 'aaabbc' -> 'a3b2c1'."""
    if not s:
        return ''
    out = []
    run = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            run += 1
        else:
            out.append(s[i - 1] + str(run))
            run = 1
    out.append(s[-1] + str(run))
    return ''.join(out)

def dec2base(n, b):
    """Convert non-negative integer n to its digit string in base b (2..16)."""
    if n == 0:
        return '0'
    digits = '0123456789abcdef'
    out = ''
    while n:
        out = digits[n % b] + out
        n //= b
    return out

