    out = [x for x in xs if x != 0]
    return out + [0] * (len(xs) - len(out))

def small_primes(n):
    """Count primes strictly below n (n >= 0)."""
    if n <= 2:
        return 0
    sieve = [True] * n
    sieve[0] = sieve[1] = False
    i = 2
    while i * i < n:
        if sieve[i]:
            for j in range(i * i, n, i):
                sieve[j] = False
        i += 1
    return sum(sieve)

def base_of_decimal(n, b):
    """Convert non-negative integer n to its digit string in base b (2..16)."""
    if n == 0:
        return '0'
    digits = '0123456789abcdef'
    out = ''
    while n:
        out = digits[n % b] + out
        n //= b
    return out

