        if out[i] < 9:
            out[i] += 1
            return out
        out[i] = 0
    return [1] + out

def rot_shift(text, k):
    """Shift each alphabetic character k positions forward, wrapping within its case."""
    out = []
    for ch in text:
        if 'a' <= ch <= 'z':
            out.append(chr((ord(ch) - 97 + k) % 26 + 97))
        elif 'A' <= ch <= 'Z':
            out.append(chr((ord(ch) - 65 + k) % 26 + 65))
        else:
            out.append(ch)
    return ''.join(out)

def count_primes_under(n):
    """Count primes strictly below n (n >= 0)."""
    if n <= 2:
        return 0
    sieve = [True] * n
    sieve[0] = sieve[1] = False
    i = 2
    while i * i < n:
        if sieve[i]:
            for j in range(i * i, n, i):
                sieve[j] = False
        i += 1
    return sum(sieve)

