def frequentest(xs):
    """Most frequent value in xs; ties broken by the smaller value."""
    counts = {}
    for x in xs:
        counts[x] = counts.get(x, 0) + 1
    best = None
    best_n = 0
    for x in sorted(counts):
        if counts[x] > best_n:
            best = x
            best_n = counts[x]
    return best

def rot13_shift(s):
    """Apply ROT13 to alphabetic characters, leaving others unchanged."""
    out = []
    for ch in s:
        if 'a' <= ch <= 'z':
            out.append(chr((ord(ch) - 97 + 13) % 26 + 97))
        elif 'A' <= ch <= 'Z':
            out.append(chr((ord(ch) - 65 + 13) % 26 + 65))
        else:
            out.append(ch)
    return ''.join(out)

def encode_runs(s):
    """Run-length encode a string: 'aaabbc' -> 'a3b2c1'."""
    if not s:
        return ''
    out = []
    run = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            run += 1
        else:
            out.append(s[i - 1] + str(run))
            run = 1
    out.append(s[-1] + str(run))
    return ''.join(out)

def decimal_to_roman(n):
    """Convert an integer (1..3999) to a Roman numeral string."""
    parts = [(1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
             (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
             (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')]
    out = []
    for value, symbol in parts:
        while n >= value:
            out.append(symbol)
            n -= value
    return ''.join(out)

