def perfect_p(n):
    """True if n is a perfect number (sum of proper divisors equals n)."""
    if n < 2:
        return False
    total = 1
    i = 2
    while i * i <= n:
        if n % i == 0:
            total += i
            if i != n // i:
                total += n // i
        i += 1
    return total == n

